/* Amber Minimal Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="amber-minimal-light"] {
  --background: hsl(300 50% 100%);
  --foreground: hsl(300 0% 15.03%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(300 0% 15.03%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(300 0% 15.03%);
  --primary: hsl(36.29 90.5% 53.69%);
  --primary-foreground: hsl(0 0% 0%);
  --secondary: hsl(300 0% 96.06%);
  --secondary-foreground: hsl(214.99 15.5% 34.68%);
  --muted: hsl(300 0% 97.37%);
  --muted-foreground: hsl(219.97 7.71% 45.75%);
  --accent: hsl(48.05 99.99% 97.01%);
  --accent-foreground: hsl(22.04 76.6% 31.8%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(220.01 24.1% 91.61%);
  --input: hsl(220.01 24.1% 91.61%);
  --ring: hsl(36.29 90.5% 53.69%);
  --chart-1: hsl(36.29 90.5% 53.69%);
  --chart-2: hsl(32.72 99.9% 43.03%);
  --chart-3: hsl(27.04 99.37% 36.06%);
  --chart-4: hsl(22.04 76.6% 31.8%);
  --chart-5: hsl(22.83 88.39% 25.09%);
  --radius: 0.375rem;
  --sidebar: hsl(300 0% 97.37%);
  --sidebar-foreground: hsl(300 0% 15.03%);
  --sidebar-primary: hsl(36.29 90.5% 53.69%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(48.05 99.99% 97.01%);
  --sidebar-accent-foreground: hsl(22.04 76.6% 31.8%);
  --sidebar-border: hsl(220.01 24.1% 91.61%);
  --sidebar-ring: hsl(36.29 90.5% 53.69%);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 8px;
  --shadow-spread: -1px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 4px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 4px 8px -1px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 1px 2px -2px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 2px 4px -2px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 4px 6px -2px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 4px 8px -1px hsl(0 0% 0% / 0.1), 0px 8px 10px -2px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 4px 8px -1px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

